let kbEditingId='';
const kbFields=['category','title','content','source','source_url','applicability','version','effective_from','effective_to','validity_status'];
function kbPayload(){return Object.fromEntries(kbFields.map(key=>[key,$('#kb-'+key.replaceAll('_','-')).value.trim()]));}
function kbFill(record){kbEditingId=record?.id||'';for(const key of kbFields){const control=$('#kb-'+key.replaceAll('_','-'));control.value=record?.[key]||(key==='validity_status'?($('#kb-category').value==='regulation'?'unknown':'not_applicable'):'');}$('#kb-editing').textContent=kbEditingId?'正在编辑：'+record.title+' · v'+record.revision+'。保存后会生成新修订并退回待审核。':'新建内容会先保存为“待审核”，不会用于报告生成。';$('#kb-save').textContent=kbEditingId?'保存新修订':'保存待审核条目';}
function kbStatusLabel(status){return {draft:'待审核',approved:'审核通过',retired:'已停用'}[status]||status;}
async function loadKnowledge(){const data=await api('/api/knowledge');$('#kb-category').replaceChildren();for(const [key,label] of Object.entries(data.categories)){const opt=el('option',label);opt.value=key;$('#kb-category').append(opt);}$('#kb-count').textContent=`${data.records.length} 条 · ${data.records.filter(r=>r.status==='approved').length} 条可检索`;$('#kb-records').replaceChildren();if(!data.records.length){$('#kb-records').append(el('p','知识库还没有条目。请录入经核验的知识并审核后，才会进入报告检索。','empty-small'));return;}for(const record of data.records){const card=el('article',undefined,'evidence-item');card.append(el('strong',data.categories[record.category]+' · '+record.title+' · '+kbStatusLabel(record.status)));card.append(el('p',(record.content||'').slice(0,520)+(record.content.length>520?'…':'')));card.append(el('small',['来源：'+record.source,record.version?'版本：'+record.version:'',record.applicability?'适用范围：'+record.applicability:'',record.effective_from?'生效：'+record.effective_from:'',record.effective_to?'失效：'+record.effective_to:'',record.reviewed_by?'审核人：'+record.reviewed_by:''].filter(Boolean).join(' · ')));card.append(el('small','修订 v'+record.revision+' · '+record.updated_at));const actions=el('div',undefined,'paragraph-actions');actions.append(button('编辑',()=>kbFill(record)));if(record.status!=='approved')actions.append(button('审核通过',async()=>{const reviewer=prompt('请输入审核人姓名（请确认来源、适用范围和有效期）');if(!reviewer?.trim())return;await post('/api/knowledge/'+record.id+'/status',{status:'approved',reviewed_by:reviewer.trim()});await loadKnowledge();notify('条目已审核通过并加入知识检索');}));if(record.status!=='retired')actions.append(button('停用',async()=>{if(!confirm('停用后将不再参与检索，历史版本会保留。确定继续？'))return;await post('/api/knowledge/'+record.id+'/status',{status:'retired'});await loadKnowledge();}));if(record.status==='retired')actions.append(button('恢复为待审核',async()=>{await post('/api/knowledge/'+record.id+'/status',{status:'draft'});await loadKnowledge();}));card.append(actions);$('#kb-records').append(card);}}
$('#kb-save').onclick=async()=>{try{const payload=kbPayload();const path=kbEditingId?'/api/knowledge/'+kbEditingId+'/update':'/api/knowledge';await post(path,payload);kbFill(null);$('#kb-message').textContent='已保存为待审核条目；请核对内容、来源、适用范围和有效期后再批准。';$('#kb-message').classList.remove('hidden');await loadKnowledge();}catch(error){notify(error.message);}};
$('#kb-clear').onclick=()=>{kbFill(null);$('#kb-message').classList.add('hidden');};
$('#kb-category').onchange=()=>{$('#kb-validity-status').value=$('#kb-category').value==='regulation'?'unknown':'not_applicable';};
$('#kb-search').onclick=async()=>{try{const query=$('#kb-query').value.trim();const result=await api('/api/knowledge/search?q='+encodeURIComponent(query)+'&limit=12');$('#kb-search-results').replaceChildren();$('#kb-search-meta').textContent='检索方式：'+({hybrid_qdrant_rrf:'关键词 + 语义向量 + RRF 融合',keyword_fallback:'关键词回退（语义索引未就绪）',empty:'知识库暂无已审核条目'}[result.retrieval_mode]||result.retrieval_mode)+' · 仅审核通过、当前有效的知识参与。';if(!result.results.length)$('#kb-search-results').append(el('p','没有找到可用的已审核条目。','empty-small'));for(const item of result.results){const card=el('div',undefined,'evidence-item');card.append(el('strong',item.source+' · '+item.locator),el('p',item.text),el('small',['适用范围：'+(item.applicability||'未注明'),'来源：'+(item.source_document||'未注明'),'有效状态：'+(item.validity_status||'未注明'),item.effective_from?'生效：'+item.effective_from:'',item.effective_to?'失效：'+item.effective_to:'','审核人：'+(item.reviewed_by||'未记录')].filter(Boolean).join(' · ')));if(item.source_url){const link=el('a','打开原始来源');link.href=item.source_url;link.target='_blank';link.rel='noopener noreferrer';card.append(link);}$('#kb-search-results').append(card);}}catch(error){notify(error.message);}};
$('#kb-query').onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();$('#kb-search').click();}};
let measureEditingId='';
function clearMeasureForm(){measureEditingId='';for(const id of ['measure-source-file','measure-source-locator','measure-recommendation','measure-response','measure-reviewer'])$('#'+id).value='';$('#measure-disposition').value='pending';$('#measure-section').value='4 安全对策措施采纳情况';$('#measure-editing').textContent='每条决定项必须能回溯到原建议；已采纳项需填写具体设计落实内容。';$('#measure-save').textContent='保存建议';}
function fillMeasureForm(item){measureEditingId=item.id;$('#measure-source-file').value=item.source_file;$('#measure-source-locator').value=item.source_locator;$('#measure-recommendation').value=item.recommendation;$('#measure-disposition').value=item.disposition;$('#measure-response').value=item.design_response;$('#measure-section').value=item.report_section;$('#measure-reviewer').value=item.reviewed_by;$('#measure-editing').textContent='正在编辑该建议，当前修订 v'+item.revision+'；保存后会保留旧版本记录。';$('#measure-save').textContent='保存修订';}
async function loadMeasures(){if(!selected||!$('#measure-list'))return;try{const result=await api(endpoint('measures'));$('#measure-list').replaceChildren();if(!result.items.length){$('#measure-list').append(el('p','尚无建议条目。可以手工添加，或将安全条件综合分析报告标记为对应资料类型后抽取候选。','empty-small'));return;}for(const item of result.items){const card=el('article',undefined,'evidence-item');card.append(el('strong','['+({pending:'待确认',adopted:'采纳',partial:'部分采纳',not_adopted:'未采纳',not_applicable:'不适用'}[item.disposition]||item.disposition)+'] '+item.recommendation),el('p','来源：'+item.source_file+' · '+item.source_locator),el('small','设计落实/理由：'+(item.design_response||'待填写')+' · 报告位置：'+(item.report_section||'未指定')+' · 确认人：'+(item.reviewed_by||'待确认')));card.append(button('编辑',()=>fillMeasureForm(item)));$('#measure-list').append(card);}}catch(error){if(!/项目不存在/.test(error.message))notify(error.message);}}
$('#measure-save').onclick=async()=>{try{const payload={...(measureEditingId?{id:measureEditingId}:{}),recommendation:$('#measure-recommendation').value,source_file:$('#measure-source-file').value,source_locator:$('#measure-source-locator').value,source_evidence_id:'',disposition:$('#measure-disposition').value,design_response:$('#measure-response').value,report_section:$('#measure-section').value,reviewed_by:$('#measure-reviewer').value};await post(endpoint('measures'),payload);clearMeasureForm();await loadMeasures();notify('安全建议已保存');}catch(error){notify(error.message);}};
$('#measure-clear').onclick=clearMeasureForm;
$('#extract-measures').onclick=async()=>{if(!selectedModel()){openModelSettings();notify('先选择模型以抽取待核对的建议候选');return;}const button=$('#extract-measures');button.disabled=true;try{const result=await post(endpoint('measures'),{operation:'extract',model_id:selectedModel()});await loadMeasures();notify('已新增 '+result.count+' 条待确认建议候选，请逐条核对原文和出处');}catch(error){notify(error.message);}finally{button.disabled=false;}};
